window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[157]={"id":"157","numero":157,"titre":"Sepsis · Bactériémie · Fongémie","objectifs":[{"id":"157-1","rang":"A","rubrique":"Définition","titre":"Connaître la définition d'une bactériémie, d'une fongémie et leur risque évolutif","contenu":"<p>Le terme historique <span class=\"kw-def\">« septicémie »</span> est <strong>abandonné</strong> au profit de\n      <span class=\"kw-def\">bactériémie</span>, <span class=\"kw-def\">fongémie</span>, <span class=\"kw-def\">virémie</span>\n      ou <span class=\"kw-def\">parasitémie</span> selon l'agent en cause.</p>\n      <p>La <strong><span class=\"kw-def\">bactériémie</span></strong> (resp. <strong><span class=\"kw-def\">fongémie</span></strong>)\n      désigne une <span class=\"kw-def\">infection du compartiment sanguin</span> par une bactérie (resp. un champignon).\n      Le diagnostic est <strong>microbiologique</strong> : ce sont <span class=\"kw-clinique\">les</span> <span class=\"kw-bio\">hémocultures</span> qui le posent.</p>\n      <p>Deux axes caractérisent une <span class=\"kw-clinique\">bactériémie</span> :</p>\n      <table >\n        <thead><tr><th>Axe</th><th>Catégories</th></tr></thead>\n        <tbody>\n          <tr><td>Foyer <span class=\"kw-etio\">infectieux</span></td><td><span class=\"kw-clinique\">Bactériémie</span> <strong>isolée</strong> (sans foyer identifié) ou <strong>associée</strong> à un foyer <span class=\"kw-etio\">infectieux</span> identifié</td></tr>\n          <tr><td>Caractère compliqué</td><td>Non compliquée, ou compliquée : <span class=\"kw-def\">sepsis</span>, <span class=\"kw-def\">choc septique</span>, <span class=\"kw-def\">SRIS</span>, <span class=\"kw-alerte\">localisations septiques secondaires</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Risque évolutif.</strong> Une <span class=\"kw-clinique\">bactériémie</span>/fongémie peut évoluer\n      vers un <span class=\"kw-def\">sepsis</span> puis un <span class=\"kw-def\">choc septique</span> (<span class=\"kw-def\">mortalité</span> élevée),\n      et se compliquer de <span class=\"kw-alerte\">localisations septiques secondaires</span> (<span class=\"kw-def\">endocardite</span>, métastases\n      septiques sur matériel étranger, spondylodiscite…).</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 158 — <span class=\"kw-def\">Sepsis</span> et <span class=\"kw-def\">choc septique</span></em></p>","frequence":0},{"id":"157-2","rang":"B","rubrique":"Épidémiologie","titre":"Connaître la fréquence des bactériémies/fongémies et la fréquence de leurs complications","contenu":"<ul>\n        <li>Une <span class=\"kw-clinique\">bactériémie</span>/fongémie concerne environ <span class=\"kw-chiffre\">1 %</span> des patients hospitalisés.</li>\n        <li>Environ <span class=\"kw-chiffre\">25 %</span> des bactériémies/fongémies s'accompagnent de signes de\n        <span class=\"kw-alerte\">détresse hémodynamique</span> (<span class=\"kw-def\">sepsis</span>, <span class=\"kw-def\">choc septique</span>).</li>\n        <li>À l'inverse, seuls <span class=\"kw-chiffre\">40 %</span> des <span class=\"kw-def\">sepsis</span> / chocs septiques sont associés à une\n        <span class=\"kw-clinique\">bactériémie</span> documentée.</li>\n        <li>Environ <span class=\"kw-chiffre\">20 %</span> des bactériémies sont <span class=\"kw-etio\">liées à un cathéter\n        vasculaire</span>.</li>\n      </ul>\n      <div class=\"callout callout-info\"><strong>À retenir.</strong> <span class=\"kw-bio\">Hémocultures</span> négatives + tableau de <span class=\"kw-def\">sepsis</span> = situation\n      fréquente (<span class=\"kw-chiffre\">60 %</span> des <span class=\"kw-def\">sepsis</span> ne sont pas bactériémiques). Une <span class=\"kw-bio\">hémoculture</span> négative <strong>n'élimine pas</strong>\n      le <span class=\"kw-def\">sepsis</span> et ne fait pas suspendre la prise en charge.</div>","frequence":0},{"id":"157-3","rang":"A","rubrique":"Diagnostic positif","titre":"Savoir rechercher sur les éléments de l'anamnèse et cliniques les éléments d'orientation pour déterminer le site infectieux, et les localisations septiques secondaires","contenu":"<p><strong>Situations cliniques évocatrices</strong> d'une <span class=\"kw-clinique\">bactériémie</span>/fongémie :</p>\n      <ul>\n        <li><span class=\"kw-clinique\">Fièvre élevée</span> ± <span class=\"kw-clinique\">frissons</span>, surtout en cas de foyers\n        <span class=\"kw-etio\">infectieux</span> multiples.</li>\n        <li><span class=\"kw-clinique\">Fièvre</span> chez un <span class=\"kw-etio\">patient neutropénique</span> ou <span class=\"kw-etio\">porteur de matériel\n        étranger</span> (cathéter veineux central ++).</li>\n        <li><span class=\"kw-alerte\">Piège :</span> certaines bactériémies à <span class=\"kw-etio\">entérobactéries</span> se\n        traduisent par une <span class=\"kw-alerte\">hypothermie</span> et non une <span class=\"kw-clinique\">fièvre</span>.</li>\n      </ul>\n      <p><strong>Anamnèse — rechercher un <span class=\"kw-def\">terrain</span> favorisant :</strong></p>\n      <ul>\n        <li><span class=\"kw-def\">Contact</span> récent avec le milieu de soins (dont <span class=\"kw-etio\">EHPAD</span>).</li>\n        <li>Gestes invasifs récents et/ou présence de <span class=\"kw-etio\">matériel étranger</span>.</li>\n        <li><span class=\"kw-etio\">Immunodépression</span> ou <span class=\"kw-def\">facteurs de risque</span> d'infection.</li>\n        <li>Prise récente de traitements anti-<span class=\"kw-etio\">infectieux</span>.</li>\n        <li><span class=\"kw-etio\">Éthylisme</span> ; brèche ostéo-méningée ; retour de zone tropicale ou d'endémie palustre.</li>\n      </ul>\n      <p><strong>Examen clinique — rechercher le foyer <span class=\"kw-etio\">infectieux</span></strong> (par ordre de fréquence :\n      <span class=\"kw-etio\">pulmonaire</span> &gt; <span class=\"kw-etio\">intra-abdominal</span> &gt;\n      <span class=\"kw-etio\">urinaire</span>) :</p>\n      <table >\n        <thead><tr><th>Foyer</th><th>Signes d'appel</th></tr></thead>\n        <tbody>\n          <tr><td>Pulmonaire</td><td><span class=\"kw-clinique\">Foyer auscultatoire</span> ; <span class=\"kw-radio\">condensation</span> alvéolaire radiographique</td></tr>\n          <tr><td>Digestif</td><td><span class=\"kw-clinique\">Signes digestifs</span> ; défense abdominale localisée ou diffuse</td></tr>\n          <tr><td>Urinaire</td><td><span class=\"kw-clinique\">Signes de cystite</span> ; urines troubles ; <span class=\"kw-bio\">BU leucocytes + nitrites</span> ; douleur du flanc</td></tr>\n          <tr><td>Ostéo-articulaire</td><td><span class=\"kw-clinique\">Douleurs articulaires / rachidiennes</span> ; signes d'arthrite</td></tr>\n          <tr><td>Matériel étranger</td><td>Cicatrices témoignant d'un dispositif implanté</td></tr>\n          <tr><td>Neuro-méningé</td><td><span class=\"kw-clinique\">Signes neurologiques focaux</span> ou <span class=\"kw-clinique\">signes méningés</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Localisations septiques secondaires.</strong> Toute <span class=\"kw-clinique\">bactériémie</span> impose\n      de rechercher des foyers métastatiques à distance (<span class=\"kw-def\">endocardite</span>, spondylodiscite,\n      <span class=\"kw-clinique\">abcès</span> profonds, arthrite) — d'autant plus en cas de germe à fort tropisme (<em>S. aureus</em>) ou de bactériémie\n      persistante.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 151 — <span class=\"kw-def\">Méningite</span> - <span class=\"kw-clinique\">méningoencéphalite</span> · 152 — <span class=\"kw-def\">Endocardite</span> infectieuse</em></p>","frequence":0},{"id":"157-4","rang":"A","rubrique":"Étiologies","titre":"Connaître les agents infectieux à l'origine des bactériémies, ainsi que leur porte d'entrée et le terrain associé","contenu":"<p>L'orientation étiologique d'une <span class=\"kw-clinique\">bactériémie</span> croise deux entrées : le <strong><span class=\"kw-def\">terrain</span></strong> du patient et\n      la <strong><span class=\"kw-clinique\">porte d'entrée</span> / le site</strong> <span class=\"kw-etio\">infectieux</span>.</p>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;\">Orientation selon le <span class=\"kw-def\">terrain</span></h4>\n      <table >\n        <thead><tr><th>Terrain</th><th>Micro-organismes</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-etio\">Neutropénie courte durée</span></td><td><span class=\"kw-etio\">BGN</span> ; <span class=\"kw-etio\">staphylocoques</span>, streptocoques, <span class=\"kw-etio\">entérocoques</span></td></tr>\n          <tr><td><span class=\"kw-etio\">Neutropénie prolongée</span> (<span class=\"kw-chiffre\">&gt; 7 j</span>)</td><td>Idem + <span class=\"kw-etio\">Pseudomonas aeruginosa</span> ; levures</td></tr>\n          <tr><td><span class=\"kw-etio\">Splénectomie / asplénie</span> ; myélome, LLC</td><td><span class=\"kw-etio\">Pneumocoque</span>, <span class=\"kw-etio\">méningocoque</span>, <em><span class=\"kw-etio\">Haemophilus</span></em> (bactéries encapsulées)</td></tr>\n          <tr><td><span class=\"kw-etio\">VIH</span></td><td><span class=\"kw-etio\">Pneumocoque</span> ; <em><span class=\"kw-etio\">Pseudomonas</span> aeruginosa</em></td></tr>\n          <tr><td><span class=\"kw-etio\">Infection associée aux soins</span></td><td><span class=\"kw-alerte\">Bactéries multi-résistantes</span>, <em>Staphylococcus aureus</em> ; levures</td></tr>\n        </tbody>\n      </table>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;\">Orientation selon le site / la <span class=\"kw-clinique\">porte d'entrée</span></h4>\n      <table >\n        <thead><tr><th>Site</th><th>Agents <span class=\"kw-etio\">infectieux</span></th><th><span class=\"kw-def\">Facteurs de risque</span></th></tr></thead>\n        <tbody>\n          <tr><td>Peau</td><td><strong><span class=\"kw-etio\">Staphylocoques</span></strong> (<em>aureus</em>, coagulase négative) ; <strong><span class=\"kw-etio\">streptocoques</span></strong> (<em>S. pyogenes</em>)</td><td>Toxicomanie ; <span class=\"kw-clinique\">érysipèle</span> ; plaie, brûlures</td></tr>\n          <tr><td>Tube digestif</td><td>Entérobactéries (<em><span class=\"kw-etio\">E. coli</span></em> ++) ; <span class=\"kw-etio\">entérocoques</span> ; anaérobies ; levures (<em><span class=\"kw-etio\">Candida</span></em>)</td><td><span class=\"kw-def\">Cirrhose</span> (infection d'<span class=\"kw-clinique\">ascite</span>) ; diverticules, tumeurs coliques</td></tr>\n          <tr><td>Voies biliaires</td><td>Entérobactéries (<em><span class=\"kw-etio\">E. coli</span></em> ++) ; <span class=\"kw-etio\">entérocoques</span> ; anaérobies</td><td>Lithiase biliaire ; cholangite ; <span class=\"kw-imagerie\">CPRE</span></td></tr>\n          <tr><td>Poumon</td><td><strong><span class=\"kw-etio\">Pneumocoque</span></strong> ; <em><span class=\"kw-etio\">Haemophilus</span></em> ; <em><span class=\"kw-etio\">Klebsiella</span> pneumoniae</em></td><td><span class=\"kw-etio\">Alcoolisme</span> ; inhalation ; sujet âgé</td></tr>\n          <tr><td>Endocarde</td><td><span class=\"kw-etio\">Staphylocoques</span> ; streptocoques ; <span class=\"kw-etio\">entérocoques</span></td><td>Cathéter veineux ++ ; valvulopathie ; gestes dentaires</td></tr>\n          <tr><td>Voies urinaires</td><td>Entérobactéries ; <span class=\"kw-etio\">entérocoques</span> ; <em><span class=\"kw-etio\">Pseudomonas</span> aeruginosa</em></td><td>Obstacle des voies excrétrices ; sondage à demeure ; manœuvre urologique</td></tr>\n          <tr><td>Voies vasculaires</td><td><span class=\"kw-etio\">Staphylocoques</span> ; BGN (<em><span class=\"kw-etio\">E. coli</span></em>) ; levures (<em><span class=\"kw-etio\">Candida</span></em>)</td><td>Toxicomanie ; cathéter veineux ++</td></tr>\n          <tr><td>Méninges</td><td><span class=\"kw-etio\">Pneumocoque</span> ; <span class=\"kw-ttt\">méningocoque</span> ; <em><span class=\"kw-etio\">Haemophilus</span></em> ; <em><span class=\"kw-etio\">Listeria</span></em></td><td>Brèche ostéo-méningée ; post-opératoire de neurochirurgie</td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 152 — <span class=\"kw-def\">Endocardite</span> infectieuse · 191 — <span class=\"kw-clinique\">Fièvre</span> chez l'immunodéprimé</em></p>","frequence":2},{"id":"157-5","rang":"B","rubrique":"Étiologies","titre":"Connaître les agents infectieux à l'origine des fongémies, ainsi que leur porte d'entrée et le terrain associé","contenu":"<p>L'espèce la plus fréquemment en cause est <strong><span class=\"kw-etio\">Candida albicans</span></strong>\n      (puis <span class=\"kw-etio\">C. glabrata</span>). <span class=\"kw-clinique\">Les</span> <em><span class=\"kw-etio\">Candida</span></em> font partie de la <span class=\"kw-etio\">flore\n      commensale</span> de la cavité buccale et de l'ensemble du tube digestif.</p>\n      <p><strong>Portes d'entrée :</strong></p>\n      <ul>\n        <li><span class=\"kw-etio\">Cathéter vasculaire</span> ; <span class=\"kw-ttt\">chirurgie</span> abdominale.</li>\n        <li>Lésions des muqueuses digestives.</li>\n        <li><span class=\"kw-etio\">Toxicomanie IV</span>.</li>\n      </ul>\n      <p><strong><span class=\"kw-def\">Terrain</span> à risque</strong> — <span class=\"kw-clinique\">les</span> candidémies surviennent presque toujours dans un contexte de soins :</p>\n      <ul>\n        <li>Patient <span class=\"kw-etio\">âgé</span> et <span class=\"kw-etio\">dénutri</span>.</li>\n        <li><span class=\"kw-etio\">Immunodépression</span> : neutropénie (hémato-oncologie), <span class=\"kw-ttt\">immunosuppresseurs</span>.</li>\n        <li><span class=\"kw-alerte\">Hospitalisation</span> en <span class=\"kw-etio\">réanimation</span>.</li>\n        <li><span class=\"kw-etio\">Antibiothérapie préalable</span> (déséquilibre de la flore digestive → prolifération de <em><span class=\"kw-etio\">Candida</span></em>).</li>\n        <li><span class=\"kw-etio\">VVC prolongée</span> et <span class=\"kw-etio\">nutrition parentérale</span>.</li>\n        <li><span class=\"kw-etio\">Chirurgie abdominale itérative</span> (surtout sus-mésocolique).</li>\n      </ul>\n      <div class=\"callout callout-danger\"><strong>Gravité.</strong> La candidémie est une infection grave : localisations\n      septiques secondaires fréquentes, <span class=\"kw-alerte\">mortalité ~40 %</span> et en augmentation. Le retrait du\n      cathéter est systématique.</div>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;\"><span class=\"kw-def\">Diagnostic positif</span></h4>\n      <p>Le diagnostic de fongémie est posé avec <strong><span class=\"kw-chiffre\">1 seule hémoculture</span></strong>\n      (suffisant). Le <span class=\"kw-bio\">délai de pousse</span> dépend du milieu :</p>\n      <ul>\n        <li>sur <span class=\"kw-bio\">milieu bactérien</span> : pousse <span class=\"kw-chiffre\">≥ 72 h</span> ;</li>\n        <li>sur <span class=\"kw-bio\">milieu spécifique</span> (mycologique) : pousse <span class=\"kw-chiffre\">≤ 24 h</span>.</li>\n      </ul>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;\">Bilan paraclinique de candidémie</h4>\n      <ul>\n        <li><span class=\"kw-imagerie\">TDM corps entier</span> : recherche de foyers secondaires.</li>\n        <li><span class=\"kw-imagerie\">Fond d'œil</span> : recherche de <span class=\"kw-alerte\">nodules rétiniens blanchâtres</span>\n        (choriorétinite).</li>\n        <li><span class=\"kw-imagerie\">ETT</span>, complétée par une <span class=\"kw-imagerie\">ETO</span> au moindre doute :\n        recherche d'<span class=\"kw-def\">endocardite</span>.</li>\n        <li>Si <span class=\"kw-etio\">cathéter</span> en place : <strong><span class=\"kw-ttt\">retrait\n        systématique</span></strong> (la candidémie est une indication de retrait) + <span class=\"kw-bio\">mise en\n        culture</span> du cathéter.</li>\n      </ul>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;\">Traitement de la candidémie</h4>\n      <ul>\n        <li><strong>Probabiliste :</strong> <span class=\"kw-ttt\">échinocandine IV</span>\n        (<span class=\"kw-ttt\">caspofungine</span> ou <span class=\"kw-ttt\">micafungine</span>).</li>\n        <li><strong>Adapté</strong> (après antifongigramme) : relais par <span class=\"kw-ttt\">fluconazole</span> si\n        possible, sinon poursuite de l'<span class=\"kw-ttt\">échinocandine</span>.</li>\n      </ul>\n      <div class=\"callout callout-warn\"><strong>Durée et <span class=\"kw-def\">suivi</span>.</strong> Contrôle des <span class=\"kw-bio\">hémocultures</span>\n      jusqu'à négativation, puis traitement poursuivi <span class=\"kw-chiffre\">14 jours après la négativation</span> des\n      <span class=\"kw-bio\">hémocultures</span> (en l'absence de localisation septique secondaire). Attention : ce délai\n      court <strong>à partir</strong> de la négativation, ce n'est pas la durée totale du traitement.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 191 — <span class=\"kw-clinique\">Fièvre</span> chez l'immunodéprimé.\n      Voir aussi obj-9 (indications des examens complémentaires), obj-12 (<span class=\"kw-ttt\">antibiothérapie</span> documentée) et obj-17 (<span class=\"kw-def\">suivi</span> sous traitement).</em></p>","frequence":0},{"id":"157-6","rang":"B","rubrique":"Étiologies","titre":"Connaître les particularité épidémiologiques, cliniques et des infections liées au cathéter","contenu":"<p>Environ <span class=\"kw-chiffre\">20 %</span> des bactériémies sont <span class=\"kw-etio\">liées à un cathéter\n      vasculaire</span>. Répartition des agents responsables :</p>\n      <table >\n        <thead><tr><th>Agent</th><th>Fréquence</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-etio\">Staphylocoques</span></td><td><span class=\"kw-chiffre\">50 %</span> — dont <span class=\"kw-chiffre\">2/3</span> à coagulase négative, <span class=\"kw-chiffre\">1/3</span> <em>S. aureus</em></td></tr>\n          <tr><td><span class=\"kw-etio\">BGN</span></td><td><span class=\"kw-chiffre\">33 %</span></td></tr>\n          <tr><td><span class=\"kw-etio\">Levures</span> (<em><span class=\"kw-etio\">Candida</span></em>)</td><td>Plus rares</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Diagnostic d'une infection liée au cathéter</strong> — prélever des <span class=\"kw-bio\">hémocultures\n      couplées</span> : une paire <strong>sur le cathéter</strong> et une paire <strong>en périphérie</strong>,\n      prélevées de manière concomitante.</p>\n      <div class=\"callout callout-info\"><strong>Différentiel de temps de pousse.</strong> Une pousse de l'<span class=\"kw-bio\">hémoculture</span>\n      <strong>sur cathéter</strong> en avance d'au moins <span class=\"kw-chiffre\">2 h</span> sur l'<span class=\"kw-bio\">hémoculture</span> périphérique\n      signe l'origine cathéter de la <span class=\"kw-clinique\">bactériémie</span>.</div>","frequence":2},{"id":"157-7","rang":"A","rubrique":"Étiologies","titre":"Connaître les particularités épidémiologiques et cliniques des bactériémies à Staphylococcus aureus","contenu":"<p><strong>Portage :</strong> <em>Staphylococcus aureus</em> est porté par environ <span class=\"kw-chiffre\">1/3</span>\n      de la population (fosses nasales, aisselles, périnée). En milieu communautaire il s'agit de\n      <span class=\"kw-def\">SASM</span> ; en milieu nosocomial, <span class=\"kw-chiffre\">10-20 %</span> de\n      <span class=\"kw-def\">SARM</span>. La <span class=\"kw-clinique\">porte d'entrée</span> reste <strong>inconnue dans <span class=\"kw-chiffre\">30 %</span></strong> des cas.</p>\n      <p><strong>Examen direct :</strong> <span class=\"kw-bio\">cocci Gram + en amas</span>.</p>\n      <div class=\"callout callout-danger\"><strong>Infection grave.</strong> La <span class=\"kw-clinique\">bactériémie</span> à <em>S. aureus</em> expose à :\n        <ul>\n          <li>des <span class=\"kw-alerte\">métastases septiques</span> fréquentes, notamment sur <span class=\"kw-etio\">matériel\n          étranger</span> (excellente capacité d'adhérence) ;</li>\n          <li>une <span class=\"kw-def\">endocardite</span> associée dans <span class=\"kw-chiffre\">~10 %</span> des cas ;</li>\n          <li>un risque élevé de <span class=\"kw-def\">choc septique</span>.</li>\n        </ul>\n      </div>\n      <p>Une <span class=\"kw-imagerie\">échographie cardiaque</span> est <strong>systématique</strong> pour rechercher une\n      <span class=\"kw-def\">endocardite</span>.</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 152 — <span class=\"kw-def\">Endocardite</span> infectieuse</em></p>","frequence":0},{"id":"157-8","rang":"A","rubrique":"Examens complémentaires","titre":"Connaître les modalités de prescription des prélèvements d'urgence avant antibiothérapie","contenu":"<p>Devant une suspicion de <span class=\"kw-clinique\">bactériémie</span>/fongémie, <span class=\"kw-clinique\">les</span> <span class=\"kw-bio\">hémocultures</span> doivent être\n      prélevées <strong>avant toute <span class=\"kw-ttt\">antibiothérapie</span></strong> — l'antibiotique négative rapidement les cultures et fait\n      perdre la documentation microbiologique.</p>\n      <div class=\"callout callout-danger\"><strong>Exception unique.</strong> Le <span class=\"kw-alerte\">purpura\n      fulminans</span> impose l'<span class=\"kw-ttt\">antibiothérapie immédiate</span> (<span class=\"kw-ttt\">C3G</span>) <strong>sans attendre</strong>\n      <span class=\"kw-clinique\">les</span> prélèvements : ici l'antibiotique précède l'<span class=\"kw-bio\">hémoculture</span>.</div>\n      <p>En <span class=\"kw-bio\">complément</span>, on prélève <span class=\"kw-clinique\">les</span> <strong>examens microbiologiques orientés</strong> par le foyer suspecté, eux\n      aussi avant l'<span class=\"kw-ttt\">antibiothérapie</span> chaque fois que possible :</p>\n      <ul>\n        <li><span class=\"kw-bio\">ECBU</span> si point d'appel urinaire ;</li>\n        <li><span class=\"kw-bio\">prélèvements respiratoires</span> si foyer pulmonaire ;</li>\n        <li><span class=\"kw-bio\">ponction lombaire</span> si <span class=\"kw-def\">syndrome méningé</span> ;</li>\n        <li>prélèvement de toute collection accessible (<span class=\"kw-clinique\">abcès</span>, liquide articulaire…).</li>\n      </ul>","frequence":0},{"id":"157-9","rang":"A","rubrique":"Examens complémentaires","titre":"Connaître les indications, les modalités de réalisation, d'analyse et d'interprétation des hémocultures","contenu":"<p><strong>Indications des <span class=\"kw-bio\">hémocultures</span> :</strong></p>\n      <ul>\n        <li>Tout <span class=\"kw-clinique\">syndrome <span class=\"kw-etio\">infectieux</span></span> ou <span class=\"kw-clinique\">fièvre</span> isolée inexpliquée, <strong>sans foyer évident</strong>.</li>\n        <li><span class=\"kw-def\">Sepsis</span>, <span class=\"kw-def\">choc septique</span>, suspicion d'<span class=\"kw-def\">endocardite</span>,\n        suspicion de <span class=\"kw-clinique\">bactériémie</span>/fongémie.</li>\n        <li>Même <strong>en l'absence de <span class=\"kw-clinique\">fièvre</span></strong> chez : sujet âgé, immunodéprimé, sous <span class=\"kw-ttt\">corticothérapie</span> ou sous\n        traitement antipyrétique.</li>\n      </ul>\n      <p><strong>Modalités de réalisation :</strong></p>\n      <table >\n        <thead><tr><th>Paramètre</th><th>Règle</th></tr></thead>\n        <tbody>\n          <tr><td>Asepsie</td><td>Mesures aseptiques strictes : <span class=\"kw-bio\">solution hydro-alcoolique</span>, <strong>gants non stériles</strong>, désinfection cutanée du patient</td></tr>\n          <tr><td>Volume</td><td><span class=\"kw-chiffre\">10 mL de sang par flacon</span> (<span class=\"kw-chiffre\">40-60 mL</span> au total) — faible concentration de germes dans le sang</td></tr>\n          <tr><td>Nombre</td><td><span class=\"kw-chiffre\">2 à 3 paires</span> (<span class=\"kw-chiffre\">4 à 6 flacons</span>), en un seul geste sur veine périphérique, 1 fois par <span class=\"kw-chiffre\">24 h</span></td></tr>\n          <tr><td>Paire</td><td>1 prélèvement = 2 flacons : 1 en <span class=\"kw-bio\">aérobiose</span>, 1 en <span class=\"kw-bio\">anaérobiose</span></td></tr>\n          <tr><td>Moment</td><td>Idéalement <strong>avant toute <span class=\"kw-ttt\">antibiothérapie</span></strong> (<span class=\"kw-alerte\">seule exception : purpura fulminans</span>)</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Cas particuliers :</strong></p>\n      <ul>\n        <li><strong>Dispositif intra-veineux central :</strong> <span class=\"kw-bio\">hémocultures</span> couplées, prélevées concomitamment sur le\n        cathéter ET en périphérie.</li>\n        <li><strong><span class=\"kw-clinique\">Syndrome <span class=\"kw-etio\">infectieux</span></span> persistant :</strong> répéter <span class=\"kw-clinique\">les</span> <span class=\"kw-bio\">hémocultures</span>.</li>\n        <li><strong><span class=\"kw-def\">Endocardite</span> infectieuse :</strong> répéter pour documenter le caractère persistant de la\n        <span class=\"kw-clinique\">bactériémie</span> ; <span class=\"kw-chiffre\">3 paires / 24 h</span> espacées d'<span class=\"kw-chiffre\">&gt; 1 h</span> ;\n        incubation prolongée <span class=\"kw-chiffre\">10-14 j</span> (germes à croissance lente).</li>\n      </ul>\n      <p><strong>Délais :</strong> examen direct + culture positive en <span class=\"kw-chiffre\">24-48 h</span> (délai d'autant\n      plus court que l'inoculum est important) ; identification + <span class=\"kw-bio\">antibiogramme</span> en <span class=\"kw-chiffre\">+24 h</span> ;\n      incubation standard <span class=\"kw-chiffre\">~5 j</span> avant d'éliminer <span class=\"kw-clinique\">les</span> flacons.</p>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;\">Interprétation</h4>\n      <table >\n        <thead><tr><th>Bactéries toujours pathogènes</th><th>Agents éventuellement contaminants</th></tr></thead>\n        <tbody>\n          <tr><td><em>S. aureus</em> ; <span class=\"kw-etio\">pneumocoque</span> ; <em><span class=\"kw-etio\">E. coli</span></em> et autres entérobactéries ; <em><span class=\"kw-etio\">Pseudomonas</span> aeruginosa</em> ; <em><span class=\"kw-etio\">Listeria</span></em>, <em>Brucella</em>, <em>Pasteurella</em></td><td><span class=\"kw-etio\">Staphylocoque à coagulase négative</span> ; <em>Cutibacterium acnes</em> ; <em>Corynebacterium</em> spp ; <em>Bacillus</em> spp</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>Règle d'interprétation.</strong>\n        <ul>\n          <li><strong>1 seule <span class=\"kw-bio\">hémoculture</span> positive suffit</strong> pour une <span class=\"kw-def\">fongémie</span> ou une\n          bactérie <strong>toujours pathogène</strong>.</li>\n          <li>Pour un <strong>agent éventuellement contaminant</strong>, il faut réunir : positivité d'au moins\n          <span class=\"kw-chiffre\">2 flacons de 2 paires différentes</span> au même germe + absence d'autre agent isolé +\n          contexte compatible (<span class=\"kw-clinique\">porte d'entrée</span> cutanée, matériel étranger, neutropénie).</li>\n        </ul>\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 152 — <span class=\"kw-def\">Endocardite</span> infectieuse</em></p>","frequence":0},{"id":"157-10","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître les indications des examens complémentaires au cours d'une bactériémie/fongémie","contenu":"<p><span class=\"kw-clinique\">Les</span> examens complémentaires recherchent la <strong><span class=\"kw-clinique\">porte d'entrée</span></strong> et les <strong>localisations\n      secondaires</strong>. L'imagerie est <strong>orientée par la clinique</strong>.</p>\n      <table >\n        <thead><tr><th>Situation</th><th>Examen</th></tr></thead>\n        <tbody>\n          <tr><td>Absence de point d'appel</td><td><span class=\"kw-imagerie\">TDM thoraco-abdomino-pelvienne</span> avec et sans injection (foyer profond)</td></tr>\n          <tr><td>Suspicion de thrombophlébite</td><td><span class=\"kw-imagerie\">Échodoppler</span> des gros troncs veineux</td></tr>\n          <tr><td>Suspicion d'<span class=\"kw-def\">endocardite</span></td><td><span class=\"kw-imagerie\">ETT</span> puis <span class=\"kw-imagerie\">ETO</span></td></tr>\n          <tr><td>Candidémie</td><td><span class=\"kw-imagerie\">Fond d'œil</span> (recherche de choriorétinite)</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Quand suspecter une <span class=\"kw-def\">endocardite</span> ?</strong> Devant une <span class=\"kw-clinique\">bactériémie</span> à\n      germe à tropisme endocardique : <em>Staphylococcus aureus</em>, <em><span class=\"kw-etio\">Enterococcus</span></em> sp, <em>Streptococcus</em> sp\n      (<span class=\"kw-alerte\">sauf streptocoque du groupe A et pneumocoque</span>), <em><span class=\"kw-etio\">Candida</span></em>.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 152 — <span class=\"kw-def\">Endocardite</span> infectieuse</em></p>","frequence":1},{"id":"157-11","rang":"A","rubrique":"Examens complémentaires","titre":"Connaître les modalités d'interprétation des marqueurs bio inflammatoires au cours d'une bactériémie/fongémie","contenu":"<p><strong>Aucun marqueur <span class=\"kw-ttt\">biologique</span> n'est spécifique</strong> d'une <span class=\"kw-clinique\">bactériémie</span>/fongémie. <span class=\"kw-clinique\">Les</span> éléments en\n      faveur d'une infection <span class=\"kw-etio\">bactérienne</span> :</p>\n      <ul>\n        <li><span class=\"kw-bio\">Hyperleucocytose à PNN</span> <span class=\"kw-chiffre\">&gt; 12 G/L</span>, ou au contraire\n        <span class=\"kw-bio\">leucopénie</span> <span class=\"kw-chiffre\">&lt; 4 G/L</span> ;</li>\n        <li>élévation de la <span class=\"kw-bio\">CRP</span> ;</li>\n        <li>élévation de la <span class=\"kw-bio\">procalcitonine (PCT)</span>.</li>\n      </ul>\n      <div class=\"callout callout-warn\"><strong><span class=\"kw-bio\">Procalcitonine</span> — usage limité.</strong> Une <span class=\"kw-bio\">PCT</span>\n      <span class=\"kw-chiffre\">&lt; 0,25 ng/mL</span> rend une <span class=\"kw-clinique\">bactériémie</span>/fongémie <strong>peu probable</strong>. Mais il n'y a\n      <strong>aucune justification à la doser systématiquement</strong> — son intérêt se limite à de rares situations.</div>\n      <p>Sur le plan du <strong><span class=\"kw-def\">terrain</span> et de la gravité</strong> : un terrain immunodéprimé\n      (<span class=\"kw-etio\">neutropénie</span>, <span class=\"kw-etio\">asplénie</span>) et un\n      <span class=\"kw-def\">qSOFA ≥ 2</span> signent un risque de <span class=\"kw-def\">sepsis</span>.</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 147 — <span class=\"kw-clinique\">Fièvre</span> aiguë</em></p>","frequence":0},{"id":"157-12","rang":"A","rubrique":"Prise en charge","titre":"Connaître les principes généraux de la prise en charge thérapeutique probabiliste d'une bactériémie/fongémie","contenu":"<p>L'<span class=\"kw-ttt\">antibiothérapie</span> probabiliste est une <strong>biantibiothérapie IV</strong>, choisie selon l'<span class=\"kw-bio\">examen\n      direct</span>, la bactérie suspectée, la <span class=\"kw-clinique\">porte d'entrée</span> et la présence de <span class=\"kw-alerte\">signes de gravité</span>. Durée probabiliste :\n      <span class=\"kw-chiffre\">3 jours</span> (hors <span class=\"kw-def\">endocardite</span>), avant <span class=\"kw-def\">réévaluation</span> selon la documentation.</p>\n      <div class=\"callout callout-danger\"><strong><span class=\"kw-ttt\">Antibiothérapie</span> immédiate (dès la 1ʳᵉ heure).</strong> À forte posologie,\n      bactéricide et à large spectre, dès que :\n        <ul>\n          <li><span class=\"kw-def\">sepsis</span> ou <span class=\"kw-def\">choc septique</span> ;</li>\n          <li><span class=\"kw-etio\">neutropénie</span> ou <span class=\"kw-etio\">asplénie</span> ;</li>\n          <li>foyer <span class=\"kw-etio\">infectieux</span> précis identifié.</li>\n        </ul>\n      </div>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;\">Choix selon la <span class=\"kw-clinique\">porte d'entrée</span> suspectée</h4>\n      <table >\n        <thead><tr><th>Porte d'entrée</th><th><span class=\"kw-ttt\">Antibiothérapie</span> probabiliste</th></tr></thead>\n        <tbody>\n          <tr><td>Non identifiée — infection communautaire</td><td><span class=\"kw-ttt\">C3G parentérale</span> (<span class=\"kw-ttt\">céfotaxime</span> ou <span class=\"kw-ttt\">ceftriaxone</span>) ± aminoside</td></tr>\n          <tr><td>Non identifiée — infection liée aux soins</td><td><span class=\"kw-ttt\">β-lactamine large spectre</span> (<span class=\"kw-ttt\">pipéracilline-tazobactam</span>, céfépime, ceftazidime ou <span class=\"kw-ttt\">méropénème</span>) ± <span class=\"kw-ttt\">amikacine</span> ; + <span class=\"kw-ttt\">vancomycine</span> ou <span class=\"kw-ttt\">linézolide</span> si suspicion de <span class=\"kw-etio\">staphylocoque</span> ; + <span class=\"kw-ttt\">échinocandine</span> si <span class=\"kw-ttt\">antifongique</span> justifié</td></tr>\n          <tr><td>Parties molles</td><td><strong>Membres, tête, cou :</strong> <span class=\"kw-ttt\">amoxicilline-acide clavulanique</span><br><strong>Périnée :</strong> <span class=\"kw-ttt\">pipéracilline-tazobactam</span><br><strong>Risque de <span class=\"kw-bio\">SARM</span> :</strong> ajout de <span class=\"kw-ttt\">linézolide</span></td></tr>\n          <tr><td>Digestif</td><td><span class=\"kw-ttt\">Pipéracilline-tazobactam</span> + <span class=\"kw-ttt\">gentamicine</span>, ou <span class=\"kw-ttt\">C3G</span> + <span class=\"kw-ttt\">métronidazole</span> ± aminoside ; <span class=\"kw-ttt\">échinocandine</span> si <span class=\"kw-chiffre\">≥ 3</span> critères (<span class=\"kw-alerte\">défaillance</span> hémodynamique, sexe féminin, <span class=\"kw-ttt\">chirurgie</span> sus-mésocolique, ATB &gt;<span class=\"kw-chiffre\"> 24 h</span>)</td></tr>\n          <tr><td>Urinaire</td><td><span class=\"kw-ttt\">C3G IV</span> + <span class=\"kw-ttt\">amikacine</span> ; tenir compte du risque d'<span class=\"kw-alerte\">EBLSE</span> (carbapénème + amikacine si FdR + <span class=\"kw-def\">choc septique</span>)</td></tr>\n          <tr><td>Pulmonaire</td><td><span class=\"kw-ttt\">C3G injectable</span> + macrolide ou <span class=\"kw-ttt\">lévofloxacine</span> IV ; β-lactamine large spectre si FdR de <em>P. aeruginosa</em></td></tr>\n        </tbody>\n      </table>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;\">Choix selon l'examen direct</h4>\n      <table >\n        <thead><tr><th>Examen direct</th><th>Germes évoqués</th><th><span class=\"kw-ttt\">Antibiothérapie</span> probabiliste</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-bio\">Cocci Gram + en amas</span></td><td><span class=\"kw-etio\">Staphylocoque</span></td><td><span class=\"kw-ttt\">Pénicilline M</span> ou <span class=\"kw-ttt\">céfazoline</span> (+ <span class=\"kw-ttt\">vancomycine</span> si FdR de <span class=\"kw-bio\">SARM</span>)</td></tr>\n          <tr><td><span class=\"kw-bio\">Cocci Gram + en chaînettes</span></td><td><span class=\"kw-etio\">Streptocoque</span>, <span class=\"kw-etio\">entérocoque</span></td><td><span class=\"kw-ttt\">Amoxicilline</span></td></tr>\n          <tr><td><span class=\"kw-bio\">Cocci Gram −</span></td><td><span class=\"kw-etio\">Méningocoque</span> ++</td><td><span class=\"kw-ttt\">C3G IV</span></td></tr>\n          <tr><td><span class=\"kw-bio\">Bacille Gram +</span></td><td><em><span class=\"kw-etio\">Listeria</span></em> ++</td><td><span class=\"kw-ttt\">Amoxicilline IV</span></td></tr>\n          <tr><td><span class=\"kw-bio\">Bacille Gram −</span> — foyer digestif/biliaire</td><td>Entérobactéries, <span class=\"kw-etio\">anaérobies</span></td><td><span class=\"kw-ttt\">C3G</span> (ou <span class=\"kw-ttt\">fluoroquinolone</span> si <span class=\"kw-ci\">allergie</span>) + <span class=\"kw-ttt\">métronidazole</span></td></tr>\n          <tr><td><span class=\"kw-bio\">Bacille Gram −</span> — foyer urinaire</td><td>Entérobactéries</td><td><span class=\"kw-ttt\">C3G</span> ou <span class=\"kw-ttt\">fluoroquinolone</span> ou aztréonam</td></tr>\n          <tr><td><span class=\"kw-bio\">Bacille Gram −</span> — foyer pulmonaire</td><td>Entérobactéries</td><td><span class=\"kw-ttt\">C3G</span></td></tr>\n          <tr><td><span class=\"kw-bio\">Bacille Gram −</span> — pas de foyer</td><td>Entérobactéries</td><td><span class=\"kw-ttt\">C3G IV</span> ou aztréonam (+ imidazolé si <span class=\"kw-bio\">hémoculture</span> <span class=\"kw-etio\">anaérobie</span> positive)</td></tr>\n          <tr><td><span class=\"kw-bio\">Levure</span></td><td><em><span class=\"kw-etio\">Candida</span></em> ++</td><td><span class=\"kw-ttt\">Échinocandine IV</span></td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 158 — <span class=\"kw-def\">Sepsis</span> et <span class=\"kw-def\">choc septique</span></em></p>","frequence":2},{"id":"157-13","rang":"A","rubrique":"Prise en charge","titre":"Connaître les modalités de choix de l'antibiotique selon l'agent infectieux sur documentation microbiologique","contenu":"<p>Une fois l'agent identifié, l'<span class=\"kw-ttt\">antibiothérapie</span> est <strong>adaptée à l'<span class=\"kw-bio\">antibiogramme</span></strong> avec\n      <span class=\"kw-def\">réduction du spectre</span> (désescalade). <span class=\"kw-ttt\">Antibiothérapie</span> documentée de 1ʳᵉ intention :</p>\n      <table >\n        <thead><tr><th>Agent <span class=\"kw-etio\">infectieux</span></th><th>Antibiothérapie de 1ʳᵉ intention</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-def\">SASM</span></strong></td><td><span class=\"kw-ttt\">Pénicilline M</span> (cloxacilline) ou <span class=\"kw-ttt\">céfazoline</span></td></tr>\n          <tr><td><strong><span class=\"kw-def\">SARM</span></strong></td><td><span class=\"kw-ttt\">Vancomycine</span> (glycopeptide)</td></tr>\n          <tr><td><span class=\"kw-etio\">Pneumocoque</span></td><td><span class=\"kw-ttt\">Amoxicilline</span></td></tr>\n          <tr><td><span class=\"kw-etio\">Méningocoque</span></td><td><span class=\"kw-ttt\">Céfotaxime</span> ou <span class=\"kw-ttt\">ceftriaxone</span></td></tr>\n          <tr><td><span class=\"kw-etio\">Streptocoque</span></td><td><span class=\"kw-ttt\">Amoxicilline</span></td></tr>\n          <tr><td><span class=\"kw-etio\">Entérocoque</span></td><td><span class=\"kw-ttt\">Amoxicilline</span> + <span class=\"kw-ttt\">gentamicine</span> si suspicion d'infection endovasculaire (<span class=\"kw-def\">endocardite</span>…)</td></tr>\n          <tr><td><span class=\"kw-etio\">Anaérobies</span></td><td><span class=\"kw-ttt\">Imidazolé</span> (s'ils ne sont pas déjà couverts par l'<span class=\"kw-ttt\">antibiothérapie</span> en cours)</td></tr>\n          <tr><td><em><span class=\"kw-etio\">Candida</span></em></td><td><span class=\"kw-ttt\">Fluconazole</span> ou <span class=\"kw-ttt\">échinocandine</span> (selon antifongigramme)</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\"><strong>Piège majeur EDN.</strong> La <span class=\"kw-ttt\">vancomycine</span> est\n      réservée au <span class=\"kw-def\">SARM</span>. Devant un <span class=\"kw-def\">SASM</span>, la <span class=\"kw-ttt\">vancomycine</span> est un\n      <span class=\"kw-alerte\">mauvais choix</span> : le traitement de référence est la <span class=\"kw-ttt\">pénicilline\n      M</span> ou la <span class=\"kw-ttt\">céfazoline</span>, plus efficaces sur <span class=\"kw-clinique\">les</span> souches sensibles à la méticilline.</div>\n      <p><strong>Modalités :</strong> voie parentérale initiale ; relais per os possible sur avis spécialisé, en\n      l'absence de <span class=\"kw-alerte\">signes de gravité</span>, d'<span class=\"kw-def\">endocardite</span>, de <span class=\"kw-clinique\">vomissements</span> ou de malabsorption. Durée variable :\n      <span class=\"kw-chiffre\">5-14 j</span> en règle générale ; <span class=\"kw-chiffre\">≥ 14 j</span> pour une <span class=\"kw-clinique\">bactériémie</span> à\n      <em>S. aureus</em> ou une fongémie.</p>","frequence":3},{"id":"157-14","rang":"A","rubrique":"Prise en charge","titre":"Connaître les principes du traitement de la porte d'entrée","contenu":"<p>L'<span class=\"kw-ttt\">antibiothérapie</span> ne suffit pas : il faut traiter la <strong><span class=\"kw-clinique\">porte d'entrée</span></strong>, le <strong>foyer\n      <span class=\"kw-etio\">infectieux</span> initial</strong> et <span class=\"kw-clinique\">les</span> <strong>localisations secondaires</strong>. On peut avoir recours à :</p>\n      <ul>\n        <li><strong>Traitement médical :</strong> <span class=\"kw-ttt\">antibiothérapie</span> prolongée.</li>\n        <li><strong>Traitement chirurgical / invasif.</strong></li>\n        <li><span class=\"kw-ttt\">Ablation du cathéter</span> en cause.</li>\n        <li><strong><span class=\"kw-ttt\">Drainage</span></strong> des <span class=\"kw-clinique\">abcès</span>, empyèmes ou collections — milieux où <span class=\"kw-clinique\">les</span> antibiotiques pénètrent\n        difficilement (<span class=\"kw-ttt\">drainage</span> radiologique, chirurgical, percutané ou endoscopique).</li>\n      </ul>\n      <div class=\"callout callout-info\"><strong>À retenir.</strong> Une collection non drainée entretient la <span class=\"kw-clinique\">bactériémie</span>\n      malgré une <span class=\"kw-ttt\">antibiothérapie</span> adaptée : le contrôle de la <span class=\"kw-clinique\">porte d'entrée</span> conditionne la guérison.</div>","frequence":0},{"id":"157-15","rang":"B","rubrique":"Prise en charge","titre":"Connaître les modalités de contrôle dela source infectieuse","contenu":"<p>Le <span class=\"kw-def\">contrôle de la source</span> regroupe tous <span class=\"kw-clinique\">les</span> gestes qui suppriment le réservoir\n      <span class=\"kw-etio\">infectieux</span>, en <span class=\"kw-bio\">complément</span> de l'<span class=\"kw-ttt\">antibiothérapie</span> :</p>\n      <ul>\n        <li><span class=\"kw-ttt\">Drainage</span> d'une collection, d'un <span class=\"kw-clinique\">abcès</span> ou d'un <span class=\"kw-clinique\">empyème</span> ;</li>\n        <li><span class=\"kw-ttt\">ablation du matériel étranger</span> infecté (cathéter, sonde, prothèse) ;</li>\n        <li><strong><span class=\"kw-ttt\">geste chirurgical</span></strong> sur le foyer (lavage, <span class=\"kw-ttt\">exérèse</span>, dérivation).</li>\n      </ul>\n      <div class=\"callout callout-warn\"><strong>Déterminant pronostique.</strong> Un contrôle de source\n      <strong>précoce</strong> est un facteur pronostique majeur. Tant que la source n'est pas contrôlée, la\n      <span class=\"kw-clinique\">bactériémie</span> peut persister et <span class=\"kw-clinique\">les</span> <span class=\"kw-bio\">hémocultures</span> rester positives malgré une <span class=\"kw-ttt\">antibiothérapie</span> adaptée.</div>","frequence":1},{"id":"157-16","rang":"B","rubrique":"Prise en charge","titre":"Connaître les modalités d'organisation du suivi d'une bactériémie à Staphylococcus aureus","contenu":"<p>La <span class=\"kw-clinique\">bactériémie</span> à <em>S. aureus</em> impose un <span class=\"kw-def\">suivi</span> structuré.</p>\n      <ul>\n        <li><strong><span class=\"kw-bio\">Hémocultures</span> de contrôle :</strong> vérifier la <span class=\"kw-bio\">négativation</span> sous\n        traitement, nécessaire <strong>après <span class=\"kw-chiffre\">48 h</span></strong>.</li>\n        <li><strong><span class=\"kw-imagerie\">Échographie cardiaque</span></strong> systématique (recherche d'<span class=\"kw-def\">endocardite</span>).</li>\n      </ul>\n      <div class=\"callout callout-danger\"><strong><span class=\"kw-bio\">Hémocultures</span> encore positives à<span class=\"kw-chiffre\"> 48 h</span>.</strong> La persistance de la\n      positivité oriente vers une <span class=\"kw-alerte\">localisation secondaire</span> ou une <span class=\"kw-alerte\">infection\n      endovasculaire</span> — chercher activement une <strong><span class=\"kw-def\">endocardite</span></strong> (écho cardiaque) et des métastases\n      septiques (imagerie).</div>\n      <p><strong>Durée du traitement :</strong> <span class=\"kw-chiffre\">14 jours</span> si <span class=\"kw-clinique\">bactériémie</span> non compliquée sans\n      localisation secondaire ; <span class=\"kw-chiffre\">2 à 6 semaines</span> dans le cas contraire.</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 152 — <span class=\"kw-def\">Endocardite</span> infectieuse</em></p>","frequence":0},{"id":"157-17","rang":"B","rubrique":"Prise en charge","titre":"Connaître les principes de l'antibiothérapie chez les patients atteints d'infections non communautaires","contenu":"<p><span class=\"kw-clinique\">Les</span> infections <strong>non communautaires</strong> (liées aux soins / nosocomiales) exposent à des germes\n      <span class=\"kw-alerte\">multi-résistants</span> : l'<span class=\"kw-ttt\">antibiothérapie</span> probabiliste y est plus large.</p>\n      <p>En cas de <span class=\"kw-clinique\">porte d'entrée</span> non identifiée liée aux soins, l'association repose sur :</p>\n      <ul>\n        <li>une <span class=\"kw-ttt\">β-lactamine à large spectre</span> : <span class=\"kw-ttt\">pipéracilline-tazobactam</span>, céfépime,\n        ceftazidime ou <span class=\"kw-ttt\">méropénème</span> ;</li>\n        <li>± <span class=\"kw-ttt\">amikacine</span> ;</li>\n        <li>+ <span class=\"kw-ttt\">vancomycine</span> ou <span class=\"kw-ttt\">linézolide</span> si suspicion de\n        <span class=\"kw-etio\">staphylocoque</span> (dispositif vasculaire) ;</li>\n        <li>+ <span class=\"kw-ttt\">échinocandine</span> si un traitement <span class=\"kw-ttt\">antifongique</span> est justifié.</li>\n      </ul>\n      <p><strong>Bactéries des principales infections liées aux soins :</strong></p>\n      <table >\n        <thead><tr><th>Type d'infection</th><th>Fréquence</th><th>Germes principaux</th></tr></thead>\n        <tbody>\n          <tr><td>Infection sur cathéter vasculaire</td><td><span class=\"kw-chiffre\">20 %</span> des bactériémies</td><td><span class=\"kw-etio\">Staphylocoques</span> (<span class=\"kw-chiffre\">50 %</span>) ; BGN (<span class=\"kw-chiffre\">33 %</span>) ; <em><span class=\"kw-etio\">Candida</span></em></td></tr>\n          <tr><td><span class=\"kw-def\">Infection urinaire</span> nosocomiale</td><td><span class=\"kw-chiffre\">30 %</span> des infections nosocomiales</td><td><em><span class=\"kw-etio\">E. coli</span></em> ; <span class=\"kw-etio\">entérocoques</span> ; <em><span class=\"kw-etio\">Klebsiella</span></em>, <em>P. aeruginosa</em> ; <em><span class=\"kw-etio\">Candida</span></em></td></tr>\n          <tr><td><span class=\"kw-def\">Pneumonie</span> nosocomiale / <span class=\"kw-clinique\">PAVM</span></td><td><span class=\"kw-chiffre\">15 %</span></td><td><em>P. aeruginosa</em> ; entérobactéries ; <em>S. aureus</em></td></tr>\n          <tr><td>Infection du site opératoire</td><td><span class=\"kw-chiffre\">16 %</span></td><td><em>S. aureus</em> ; autres germes selon le site</td></tr>\n        </tbody>\n      </table>\n      <p>Globalement : <span class=\"kw-def\">BGN ~60 %</span>, <span class=\"kw-def\">cocci Gram + ~30 %</span> ; top 3 des\n      germes : <em><span class=\"kw-etio\">E. coli</span></em>, <em>S. aureus</em>, <em>P. aeruginosa</em>.</p>","frequence":0},{"id":"157-18","rang":"B","rubrique":"Suivi et/ou pronostic","titre":"Connaître les modalités de surveillance de l'évolution d'une bactériémie/fongémie sous traitement","contenu":"<p>La <span class=\"kw-def\">surveillance</span> d'une <span class=\"kw-clinique\">bactériémie</span>/fongémie traitée est à la fois <strong>clinique</strong> et\n      <strong>microbiologique</strong>.</p>\n      <ul>\n        <li><strong><span class=\"kw-def\">Surveillance</span> clinique :</strong> obtention de l'<span class=\"kw-clinique\">apyrexie</span>, régression\n        des signes <span class=\"kw-etio\">infectieux</span> et hémodynamiques.</li>\n        <li><strong><span class=\"kw-bio\">Hémocultures</span> de contrôle :</strong> vérifier la <span class=\"kw-bio\">négativation</span> —\n        indispensable après <span class=\"kw-chiffre\">48 h</span> pour une <span class=\"kw-clinique\">bactériémie</span> à <em>S. aureus</em>, et répétées\n        jusqu'à négativation pour une fongémie.</li>\n      </ul>\n      <div class=\"callout callout-warn\"><strong>Persistance de la positivité.</strong> Des <span class=\"kw-bio\">hémocultures</span> encore\n      positives sous traitement adapté font rechercher une <span class=\"kw-alerte\">localisation secondaire</span>, une\n      <span class=\"kw-alerte\">infection endovasculaire</span> (<span class=\"kw-def\">endocardite</span>) ou un <strong>défaut de contrôle de la\n      source</strong>.</div>\n      <p><strong>Durée — fongémie :</strong> le traitement est poursuivi <span class=\"kw-chiffre\">14 jours après la\n      négativation</span> des <span class=\"kw-bio\">hémocultures</span> (en l'absence de localisation secondaire). Ce délai court\n      <strong>à partir</strong> de la négativation — ce n'est pas la durée totale du traitement.</p>","frequence":0}],"astuces":[],"strategie":{"urgence":"<p><strong><span class=\"kw-bio\">Hémocultures</span> :</strong> <span class=\"kw-bio\">hémocultures</span> (<span class=\"kw-chiffre\">2 à 3 paires</span>) <span class=\"kw-ttt\">AVANT toute antibiothérapie</span> — l’antibiotique négative rapidement <span class=\"kw-clinique\">les</span> cultures.<br><strong>Exception unique :</strong> <span class=\"kw-alerte\">purpura fulminans</span> → <span class=\"kw-ttt\">C3G</span> en <span class=\"kw-alerte\">urgence</span>, sans attendre les prélèvements.<br><strong>Durée probabiliste :</strong> <span class=\"kw-chiffre\">3 jours</span> (hors <span class=\"kw-def\">endocardite</span>), puis <span class=\"kw-def\">réévaluation</span> sur documentation.</p><ul><li><span class=\"kw-ttt\">Antibiothérapie immédiate</span> dès la <span class=\"kw-chiffre\">1<sup>re</sup> heure</span> (forte posologie, bactéricide, large spectre) si : <span class=\"kw-alerte\">sepsis</span> / <span class=\"kw-alerte\">choc septique</span>, <span class=\"kw-alerte\">neutropénie</span> / <span class=\"kw-alerte\">asplénie</span>, ou foyer <span class=\"kw-etio\">infectieux</span> précis identifié.</li><li>Prélever <span class=\"kw-clinique\">les</span> <span class=\"kw-bio\">examens microbiologiques orientés</span> (<span class=\"kw-bio\">ECBU</span>, prélèvements respiratoires, <span class=\"kw-bio\">ponction lombaire</span>…) avant l’<span class=\"kw-ttt\">antibiothérapie</span> chaque fois que possible.</li><li>Délais de rendu : <span class=\"kw-bio\">examen direct</span> + culture en <span class=\"kw-chiffre\">24-48 h</span> ; identification + <span class=\"kw-bio\">antibiogramme</span> en <span class=\"kw-chiffre\">+24 h</span>.</li></ul>","redflags":"<ul><li><span class=\"kw-alerte\">Détresse hémodynamique</span> : <span class=\"kw-def\">sepsis</span> ou <span class=\"kw-def\">choc septique</span> (<span class=\"kw-def\">qSOFA ≥ 2</span>) — concerne ~<span class=\"kw-chiffre\">25 %</span> des bactériémies.</li><li><span class=\"kw-alerte\">Purpura fulminans</span> : impose l’<span class=\"kw-ttt\">antibiothérapie</span> immédiate avant tout prélèvement.</li><li><span class=\"kw-def\">Terrain</span> immunodéprimé : <span class=\"kw-alerte\">neutropénie</span>, <span class=\"kw-alerte\">asplénie</span>.</li><li><span class=\"kw-alerte\">Hypothermie</span> (piège : certaines bactériémies à <span class=\"kw-etio\">entérobactéries</span> donnent une <span class=\"kw-clinique\">hypothermie</span> au lieu d’une <span class=\"kw-clinique\">fièvre</span>).</li><li><span class=\"kw-clinique\">Bactériémie</span> à <span class=\"kw-etio\">Staphylococcus aureus</span> : infection grave — <span class=\"kw-alerte\">métastases septiques</span> (matériel étranger), <span class=\"kw-def\">endocardite</span> dans <span class=\"kw-chiffre\">~10 %</span>, risque de <span class=\"kw-def\">choc septique</span>.</li><li><span class=\"kw-etio\">Candidémie</span> : <span class=\"kw-alerte\">mortalité ~40 %</span>, en augmentation.</li><li><span class=\"kw-bio\">Hémocultures</span> toujours positives <span class=\"kw-chiffre\">après 48 h</span> sous traitement adapté : <span class=\"kw-alerte\">localisation secondaire</span> ou <span class=\"kw-alerte\">infection endovasculaire</span> (chercher une <span class=\"kw-def\">endocardite</span>).</li></ul>","principes":"<p><strong>Principe :</strong> <span class=\"kw-ttt\">biantibiothérapie IV</span> probabiliste selon l’<span class=\"kw-bio\">examen direct</span>, la porte d’entrée et la gravité, puis <span class=\"kw-def\">désescalade</span> documentée sur <span class=\"kw-bio\">antibiogramme</span> + traitement de la porte d’entrée.</p><p><strong><span class=\"kw-ttt\">Antibiothérapie</span> probabiliste</strong></p><ul><li>Porte d’entrée non identifiée, <span class=\"kw-etio\">communautaire</span> : <span class=\"kw-ttt\">C3G parentérale</span> (<span class=\"kw-ttt\">céfotaxime</span> ou <span class=\"kw-ttt\">ceftriaxone</span>) ± aminoside.</li><li>Porte d’entrée non identifiée, <span class=\"kw-etio\">liée aux soins</span> : <span class=\"kw-ttt\">β-lactamine large spectre</span> (<span class=\"kw-ttt\">pipéracilline-tazobactam</span>, céfépime, ceftazidime ou <span class=\"kw-ttt\">méropénème</span>) ± <span class=\"kw-ttt\">amikacine</span> ; + <span class=\"kw-ttt\">vancomycine</span> / <span class=\"kw-ttt\">linézolide</span> si suspicion de <span class=\"kw-etio\">staphylocoque</span> ; + <span class=\"kw-ttt\">échinocandine</span> si <span class=\"kw-ttt\">antifongique</span> justifié.</li><li>Sinon adaptée à la porte d’entrée (urinaire, digestive, pulmonaire, parties molles) et à l’examen direct — cf. arbre CAT.</li></ul><p><strong><span class=\"kw-ttt\">Antibiothérapie</span> documentée (désescalade)</strong></p><ul><li><span class=\"kw-def\">SASM</span> : <span class=\"kw-ttt\">pénicilline M</span> ou <span class=\"kw-ttt\">céfazoline</span> ; <span class=\"kw-def\">SARM</span> : <span class=\"kw-ttt\">vancomycine</span>.</li><li>Piège EDN : la <span class=\"kw-ttt\">vancomycine</span> est un mauvais choix sur <span class=\"kw-def\">SASM</span> (préférer <span class=\"kw-ttt\">pénicilline M</span> / <span class=\"kw-ttt\">céfazoline</span>).</li><li>Relais <span class=\"kw-ttt\">per os</span> possible sur avis spécialisé si pas de gravité, d’<span class=\"kw-def\">endocardite</span>, de <span class=\"kw-clinique\">vomissements</span> ni de malabsorption.</li><li>Durée : <span class=\"kw-chiffre\">5-14 jours</span> en règle générale ; <span class=\"kw-chiffre\">≥ 14 jours</span> si <span class=\"kw-etio\">S. aureus</span> ou fongémie.</li></ul><p><strong>Traitement de la porte d’entrée / contrôle de source</strong></p><ul><li><span class=\"kw-ttt\">Ablation du cathéter</span> en cause (systématique en cas de <span class=\"kw-etio\">candidémie</span>).</li><li><span class=\"kw-ttt\">Drainage</span> des <span class=\"kw-clinique\">abcès</span>, empyèmes ou collections (radiologique, chirurgical, percutané, endoscopique).</li><li><span class=\"kw-ttt\">Geste chirurgical</span> sur le foyer : une collection non drainée entretient la <span class=\"kw-clinique\">bactériémie</span> malgré une ATB adaptée.</li></ul><p><strong>Candidémie</strong></p><ul><li>Probabiliste : <span class=\"kw-ttt\">échinocandine IV</span> (<span class=\"kw-ttt\">caspofungine</span> ou <span class=\"kw-ttt\">micafungine</span>).</li><li>Adapté : relais par <span class=\"kw-ttt\">fluconazole</span> si possible (antifongigramme).</li><li><span class=\"kw-ttt\">Retrait du cathéter</span> systématique ; durée <span class=\"kw-chiffre\">14 jours après négativation</span> des <span class=\"kw-bio\">hémocultures</span>.</li></ul>","suivi":"<p><strong><span class=\"kw-def\">Surveillance</span> clinique :</strong> obtention de l’<span class=\"kw-clinique\">apyrexie</span>, régression des signes <span class=\"kw-etio\">infectieux</span> et hémodynamiques.<br><strong>Surveillance microbiologique :</strong> <span class=\"kw-bio\">hémocultures</span> de contrôle pour vérifier la <span class=\"kw-bio\">négativation</span> sous traitement.</p><ul><li><span class=\"kw-clinique\">Bactériémie</span> à <span class=\"kw-etio\">S. aureus</span> : <span class=\"kw-bio\">hémocultures</span> de contrôle <span class=\"kw-chiffre\">après 48 h</span> + <span class=\"kw-imagerie\">échographie cardiaque</span> systématique (<span class=\"kw-def\">endocardite</span>).</li><li>Fongémie : <span class=\"kw-bio\">hémocultures</span> répétées jusqu’à <span class=\"kw-bio\">négativation</span>.</li><li><span class=\"kw-bio\">Hémocultures</span> persistantes positives → rechercher une <span class=\"kw-alerte\">localisation secondaire</span>, une <span class=\"kw-alerte\">infection endovasculaire</span> (<span class=\"kw-def\">endocardite</span>) ou un défaut de contrôle de la source.</li><li>Durée — <span class=\"kw-etio\">S. aureus</span> : <span class=\"kw-chiffre\">14 jours</span> si non compliquée sans localisation secondaire, <span class=\"kw-chiffre\">2 à 6 semaines</span> sinon.</li><li>Durée — fongémie : <span class=\"kw-chiffre\">14 jours après la négativation</span> des <span class=\"kw-bio\">hémocultures</span> (délai qui court à partir de la négativation, ≠ durée totale du traitement).</li></ul>"},"liensGlobaux":[{"href":"https://www.infectiologie.com/UserFiles/File/pilly-etudiant/ecn-2020-157-web.pdf","label":"Collège Pilly — Septicémies (item 157, PDF 2020)"}],"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Suspicion de bactériémie / fongémie — Hémocultures (2-3 paires) AVANT toute antibiothérapie","detail":"<h4>CAT — <span class=\"kw-clinique\">Bactériémie</span> / fongémie : du prélèvement au traitement ciblé — <span class=\"kw-bio\">Hémocultures</span> avant ATB → probabiliste selon examen direct + porte d’entrée → désescalade documentée</h4>","branches":[{"to":"t-purpura","label":"Purpura fulminans","color":"red"},{"to":"q-direct","label":"Pas de purpura — hémocultures prélevées","color":"blue"}]},{"id":"t-purpura","kind":"terminal","label":"Purpura fulminans : C3G immédiate","color":"red","detail":"<h4>Conduite</h4><ul><li><span class=\"kw-alerte\">Urgence</span> vitale : <span class=\"kw-ttt\">antibiothérapie immédiate</span> sans attendre <span class=\"kw-clinique\">les</span> <span class=\"kw-bio\">hémocultures</span> — seule exception à la règle « prélever avant de traiter ».</li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">C3G</span> parentérale (<span class=\"kw-ttt\">céfotaxime</span> ou <span class=\"kw-ttt\">ceftriaxone</span>).</li></ul><h4>Délai</h4><ul><li>Avant tout transfert et tout autre prélèvement.</li></ul>"},{"id":"q-direct","kind":"decision","label":"Résultat de l’examen direct ?","branches":[{"to":"q-cgp","label":"Cocci Gram +","color":"amber"},{"to":"t-cgn","label":"Cocci Gram −","color":"amber"},{"to":"t-bgp","label":"Bacille Gram +","color":"amber"},{"to":"q-bgn","label":"Bacille Gram −","color":"amber"},{"to":"t-levure","label":"Levure","color":"red"},{"to":"q-context","label":"Examen direct négatif","color":"blue"}]},{"id":"q-cgp","kind":"decision","label":"Forme des cocci Gram + ?","branches":[{"to":"t-cgp-amas","label":"En amas (staphylocoque)","color":"amber"},{"to":"t-cgp-chain","label":"En chaînettes (strepto / entérocoque)","color":"amber"}]},{"id":"t-cgp-amas","kind":"terminal","label":"Staphylocoque : pénicilline M / céfazoline","color":"amber","detail":"<h4>Germe</h4><ul><li>Suspicion de <span class=\"kw-etio\">staphylocoque</span> (<span class=\"kw-bio\">cocci Gram + en amas</span>).</li></ul><h4>ATB probabiliste</h4><ul><li><span class=\"kw-ttt\">Pénicilline M</span> ou <span class=\"kw-ttt\">céfazoline</span> ; ajout de <span class=\"kw-ttt\">vancomycine</span> si <span class=\"kw-def\">facteur de risque</span> de <span class=\"kw-def\">SARM</span>.</li></ul><h4>Bilan</h4><ul><li><span class=\"kw-imagerie\">Échographie cardiaque</span> systématique (<span class=\"kw-def\">endocardite</span> dans <span class=\"kw-chiffre\">~10 %</span>) et recherche de <span class=\"kw-alerte\">métastases septiques</span>.</li></ul><h4>Désescalade</h4><ul><li><span class=\"kw-def\">SASM</span> : <span class=\"kw-ttt\">pénicilline M</span> ou <span class=\"kw-ttt\">céfazoline</span> (la <span class=\"kw-ttt\">vancomycine</span> est un mauvais choix sur SASM).</li><li><span class=\"kw-def\">SARM</span> : <span class=\"kw-ttt\">vancomycine</span>.</li><li>Durée <span class=\"kw-chiffre\">14 jours</span> si non compliquée, <span class=\"kw-chiffre\">2 à 6 semaines</span> sinon.</li></ul>"},{"id":"t-cgp-chain","kind":"terminal","label":"Strepto / entérocoque : amoxicilline","color":"amber","detail":"<h4>Germe</h4><ul><li>Suspicion de <span class=\"kw-etio\">streptocoque</span> ou <span class=\"kw-etio\">entérocoque</span> (<span class=\"kw-bio\">cocci Gram + en chaînettes</span>).</li></ul><h4>ATB probabiliste</h4><ul><li><span class=\"kw-ttt\">Amoxicilline</span>.</li></ul><h4>Désescalade</h4><ul><li><span class=\"kw-etio\">Pneumocoque</span> / streptocoque : <span class=\"kw-ttt\">amoxicilline</span>.</li><li><span class=\"kw-etio\">Entérocoque</span> : <span class=\"kw-ttt\">amoxicilline</span> + <span class=\"kw-ttt\">gentamicine</span> si suspicion d’infection endovasculaire (<span class=\"kw-def\">endocardite</span>).</li></ul>"},{"id":"t-cgn","kind":"terminal","label":"Méningocoque : C3G IV","color":"amber","detail":"<h4>Germe</h4><ul><li>Suspicion de <span class=\"kw-etio\">méningocoque</span> (<span class=\"kw-bio\">cocci Gram −</span>).</li></ul><h4>ATB probabiliste</h4><ul><li><span class=\"kw-ttt\">C3G IV</span> (<span class=\"kw-ttt\">céfotaxime</span> ou <span class=\"kw-ttt\">ceftriaxone</span>).</li></ul>"},{"id":"t-bgp","kind":"terminal","label":"Listeria : amoxicilline IV","color":"amber","detail":"<h4>Germe</h4><ul><li>Suspicion de <span class=\"kw-etio\">Listeria</span> (<span class=\"kw-bio\">bacille Gram +</span>).</li></ul><h4>ATB probabiliste</h4><ul><li><span class=\"kw-ttt\">Amoxicilline IV</span>.</li></ul>"},{"id":"q-bgn","kind":"decision","label":"Porte d’entrée du bacille Gram − ?","branches":[{"to":"t-bgn-uro","label":"Porte urinaire","color":"amber"},{"to":"t-bgn-dig","label":"Porte digestive / biliaire","color":"amber"},{"to":"t-bgn-pulm","label":"Porte pulmonaire","color":"amber"},{"to":"t-bgn-nofoyer","label":"Sans foyer identifié","color":"amber"}]},{"id":"t-bgn-uro","kind":"terminal","label":"BGN urinaire : C3G + amikacine","color":"amber","detail":"<h4>Germe / porte</h4><ul><li><span class=\"kw-bio\">Bacille Gram −</span>, porte d’entrée <span class=\"kw-etio\">urinaire</span> (entérobactéries).</li></ul><h4>ATB probabiliste</h4><ul><li><span class=\"kw-ttt\">C3G IV</span> + <span class=\"kw-ttt\">amikacine</span> (si <span class=\"kw-ci\">allergie</span> : <span class=\"kw-ttt\">aztréonam</span> + <span class=\"kw-ttt\">amikacine</span>).</li></ul><h4>Risque <span class=\"kw-bio\">EBLSE</span></h4><ul><li>FdR d’entérobactérie résistante aux C<span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>3</span>G</span> + <span class=\"kw-alerte\">choc septique</span> : <span class=\"kw-ttt\">carbapénème</span> (<span class=\"kw-ttt\">imipénème</span> / <span class=\"kw-ttt\">méropénème</span>) + <span class=\"kw-ttt\">amikacine</span>.</li><li>ATCD d’IU / <span class=\"kw-etio\">colonisation</span> <span class=\"kw-bio\">EBLSE</span> <span class=\"kw-chiffre\">&lt; 3 mois</span> sans <span class=\"kw-alerte\">choc</span> : <span class=\"kw-ttt\">pipéracilline-tazobactam</span> + <span class=\"kw-ttt\">amikacine</span> si souche sensible, sinon <span class=\"kw-ttt\">carbapénème</span> + <span class=\"kw-ttt\">amikacine</span>.</li></ul>"},{"id":"t-bgn-dig","kind":"terminal","label":"BGN digestif : pip-tazo ou C3G + métronidazole","color":"amber","detail":"<h4>Germe / porte</h4><ul><li><span class=\"kw-bio\">Bacille Gram −</span>, porte <span class=\"kw-etio\">digestive / biliaire</span> (<span class=\"kw-etio\">E. coli</span>, entérobactéries, B. fragilis, <span class=\"kw-etio\">entérocoques</span>).</li></ul><h4>ATB probabiliste</h4><ul><li><span class=\"kw-ttt\">Pipéracilline-tazobactam</span> + <span class=\"kw-ttt\">gentamicine</span>, OU <span class=\"kw-ttt\">C3G</span> (ou <span class=\"kw-ttt\">fluoroquinolone</span> si <span class=\"kw-ci\">allergie</span>) + <span class=\"kw-ttt\">métronidazole</span> ± aminoside.</li></ul><h4><span class=\"kw-ttt\">Antifongique</span> associé</h4><ul><li>Ajout d’une <span class=\"kw-ttt\">échinocandine</span> si ≥ <span class=\"kw-chiffre\">3 critères</span> parmi : <span class=\"kw-alerte\">défaillance</span> hémodynamique, sexe féminin, <span class=\"kw-ttt\">chirurgie</span> sus-mésocolique, ATB en cours depuis <span class=\"kw-chiffre\">&gt; 24 h</span>.</li></ul>"},{"id":"t-bgn-pulm","kind":"terminal","label":"BGN pulmonaire : C3G + macrolide / lévofloxacine","color":"amber","detail":"<h4>Germe / porte</h4><ul><li><span class=\"kw-bio\">Bacille Gram −</span>, porte d’entrée <span class=\"kw-etio\">pulmonaire</span>.</li></ul><h4>ATB probabiliste</h4><ul><li><span class=\"kw-ttt\">C3G injectable</span> + <span class=\"kw-ttt\">macrolide IV</span>, OU <span class=\"kw-ttt\">C3G injectable</span> + <span class=\"kw-ttt\">lévofloxacine IV</span>.</li></ul><h4>Si FdR de P. aeruginosa</h4><ul><li><span class=\"kw-ttt\">β-lactamine large spectre</span> + (<span class=\"kw-ttt\">amikacine</span> ou <span class=\"kw-ttt\">tobramycine</span>) + (<span class=\"kw-ttt\">lévofloxacine</span> ou <span class=\"kw-ttt\">macrolide</span>).</li></ul>"},{"id":"t-bgn-nofoyer","kind":"terminal","label":"BGN sans foyer : C3G IV ou aztréonam","color":"amber","detail":"<h4>Germe / porte</h4><ul><li><span class=\"kw-bio\">Bacille Gram −</span> sans foyer identifié (entérobactéries).</li></ul><h4>ATB probabiliste</h4><ul><li><span class=\"kw-ttt\">C3G IV</span> ou <span class=\"kw-ttt\">aztréonam</span> ; + <span class=\"kw-ttt\">imidazolé</span> si <span class=\"kw-bio\">hémoculture anaérobie</span> positive.</li></ul>"},{"id":"t-levure","kind":"terminal","label":"Candidémie : échinocandine + retrait cathéter","color":"red","detail":"<h4>Germe</h4><ul><li>Suspicion de <span class=\"kw-etio\">Candida</span> (<span class=\"kw-bio\">levure</span> à l’examen direct) : une seule <span class=\"kw-bio\">hémoculture</span> positive suffit.</li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Échinocandine IV</span> probabiliste (<span class=\"kw-ttt\">caspofungine</span> ou <span class=\"kw-ttt\">micafungine</span>) ; relais <span class=\"kw-ttt\">fluconazole</span> selon antifongigramme.</li></ul><h4>Contrôle de source</h4><ul><li><span class=\"kw-ttt\">Retrait systématique du cathéter</span> (la candidémie est une indication de retrait) + mise en culture.</li></ul><h4>Bilan</h4><ul><li><span class=\"kw-imagerie\">Fond d’œil</span> : <span class=\"kw-alerte\">nodules rétiniens blanchâtres</span> (choriorétinite).</li><li><span class=\"kw-imagerie\">TDM corps entier</span> (foyers secondaires) ; <span class=\"kw-imagerie\">ETT</span> ± <span class=\"kw-imagerie\">ETO</span> (<span class=\"kw-clinique\">endocardite</span>).</li></ul><h4>Durée</h4><ul><li>Poursuite <span class=\"kw-chiffre\">14 jours après négativation</span> des <span class=\"kw-bio\">hémocultures</span> (hors localisation secondaire).</li></ul>"},{"id":"q-context","kind":"decision","label":"Contexte de l’infection ?","branches":[{"to":"t-comm","label":"Communautaire","color":"amber"},{"to":"t-soins","label":"Liée aux soins","color":"red"}]},{"id":"t-comm","kind":"terminal","label":"Communautaire : C3G ± aminoside","color":"amber","detail":"<h4>Contexte</h4><ul><li>Porte d’entrée <span class=\"kw-etio\">non identifiée</span>, infection <span class=\"kw-etio\">communautaire</span>.</li></ul><h4>ATB probabiliste</h4><ul><li><span class=\"kw-ttt\">C3G parentérale</span> (<span class=\"kw-ttt\">céfotaxime</span> ou <span class=\"kw-ttt\">ceftriaxone</span>) ± aminoside.</li></ul>"},{"id":"t-soins","kind":"terminal","label":"Liée aux soins : β-lactamine large spectre","color":"red","detail":"<h4>Contexte</h4><ul><li>Porte d’entrée <span class=\"kw-etio\">non identifiée</span>, infection <span class=\"kw-etio\">liée aux soins</span> (risque de <span class=\"kw-alerte\">bactéries multi-résistantes</span>).</li></ul><h4>ATB probabiliste</h4><ul><li><span class=\"kw-ttt\">β-lactamine large spectre</span> (<span class=\"kw-ttt\">pipéracilline-tazobactam</span>, <span class=\"kw-ttt\">céfépime</span>, <span class=\"kw-ttt\">ceftazidime</span> ou <span class=\"kw-ttt\">méropénème</span>) ± <span class=\"kw-ttt\">amikacine</span>.</li><li>+ <span class=\"kw-ttt\">vancomycine</span> ou <span class=\"kw-ttt\">linézolide</span> si suspicion de <span class=\"kw-etio\">staphylocoque</span> (dispositif vasculaire).</li><li>+ <span class=\"kw-ttt\">échinocandine</span> si un traitement <span class=\"kw-ttt\">antifongique</span> est justifié.</li></ul>"}]},"cards":[]};